using System;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using Knight.Presentation.Minimap;

namespace Knight.Tests.Unit;

// Independent frozen144 catalog, exported from the retained pre-annex parent.
// Test data only: production migration never reads this fixture or a workspace.
internal static class HistoricalMinimapCatalogFixture
{
    internal static MinimapTerrainCatalog Baffle()
    {
        using var encoded=new MemoryStream(Convert.FromBase64String(string.Concat(CompressedParts)),false);
        using var zip=new GZipStream(encoded,CompressionMode.Decompress);
        byte[] bytes=new byte[354960];
        zip.ReadExactly(bytes);
        TestAssert.Equal(-1,zip.ReadByte(),"frozen catalog has no extra decompressed bytes");
        TestAssert.Equal("CD66FCE70550F1D5414634B3380D2E73A98ADA2963F94EC104976AE6D0DE3566",
            Convert.ToHexString(SHA256.HashData(bytes)),"independent historical144 complete payload digest");
        return new MinimapTerrainCatalog {SerializedValues=bytes};
    }

    private static readonly string[] CompressedParts=
    [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ];
}

